typedef struct {
    int n;
    long long *tree;
} SegTree;

void build(SegTree *st, long long *arr, int node, int l, int r) {
    if (l == r) {
        st->tree[node] = arr[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(st, arr, node << 1, l, mid);
    build(st, arr, node << 1 | 1, mid + 1, r);
    st->tree[node] = MAX(st->tree[node << 1], st->tree[node << 1 | 1]);
}

void update(SegTree *st, int node, int l, int r, int idx, long long val) {
    if (l == r) {
        st->tree[node] = val;
        return;
    }
    int mid = (l + r) >> 1;
    if (idx <= mid) update(st, node << 1, l, mid, idx, val);
    else update(st, node << 1 | 1, mid + 1, r, idx, val);
    st->tree[node] = MAX(st->tree[node << 1], st->tree[node << 1 | 1]);
}

long long query_max(SegTree *st, int node, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return st->tree[node];
    int mid = (l + r) >> 1;
    long long res = -(1LL << 60);
    if (ql <= mid) res = MAX(res, query_max(st, node << 1, l, mid, ql, qr));
    if (qr > mid) res = MAX(res, query_max(st, node << 1 | 1, mid + 1, r, ql, qr));
    return res;
}

/* Find minimum index j >= x such that A[j] >= v; return n+1 if none exists */
int find_first_ge(SegTree *st, int node, int l, int r, int x, long long v) {
    if (r < x || st->tree[node] < v) return st->n + 1;
    if (l == r) return l;
    int mid = (l + r) >> 1;
    int left = find_first_ge(st, node << 1, l, mid, x, v);
    if (left != st->n + 1) return left;
    return find_first_ge(st, node << 1 | 1, mid + 1, r, x, v);
}

