struct SegmentTree {
    int n;
    vector<int> tree;
    SegmentTree(const vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        build(1, 0, n - 1, arr);
    }
    void build(int node, int l, int r, const vector<int>& arr) {
        if (l == r) {
            tree[node] = arr[l];
            return;
        }
        int mid = (l + r) / 2;
        build(node * 2, l, mid, arr);
        build(node * 2 + 1, mid + 1, r, arr);
        tree[node] = max(tree[node * 2], tree[node * 2 + 1]);
    }
    void update(int idx, int val, int node, int l, int r) {
        if (l == r) {
            tree[node] = val;
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid)
            update(idx, val, node * 2, l, mid);
        else
            update(idx, val, node * 2 + 1, mid + 1, r);
        tree[node] = max(tree[node * 2], tree[node * 2 + 1]);
    }
    int queryMax(int ql, int qr, int node, int l, int r) {
        if (ql > r || qr < l) return -INF;
        if (ql <= l && r <= qr) return tree[node];
        int mid = (l + r) / 2;
        return max(queryMax(ql, qr, node * 2, l, mid),
                   queryMax(ql, qr, node * 2 + 1, mid + 1, r));
    }
    // Find first index >= pos with value >= val
    int findFirst(int pos, int val, int node, int l, int r) {
        if (r < pos || tree[node] < val) return -1;
        if (l == r) return l;
        int mid = (l + r) / 2;
        int leftRes = findFirst(pos, val, node * 2, l, mid);
        if (leftRes != -1) return leftRes;
        return findFirst(pos, val, node * 2 + 1, mid + 1, r);
    }
};

