#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n;
    vector<long long> tree;

    SegTree(int sz = 0) { init(sz); }

    void init(int sz) {
        n = 1;
        while (n < sz) n <<= 1;
        tree.assign(2 * n, LLONG_MIN);
    }

    void build(const vector<long long>& a) {
        int sz = (int)a.size() - 1; // 1-indexed input
        init(sz);
        for (int i = 1; i <= sz; i++) tree[n + i - 1] = a[i];
        for (int i = n - 1; i >= 1; i--) tree[i] = max(tree[2 * i], tree[2 * i + 1]);
    }

    void update(int pos, long long val) {
        int p = n + pos - 1;
        tree[p] = val;
        p >>= 1;
        while (p) {
            tree[p] = max(tree[2 * p], tree[2 * p + 1]);
            p >>= 1;
        }
    }

    long long queryMax(int l, int r) {
        long long res = LLONG_MIN;
        int L = n + l - 1, R = n + r - 1;
        while (L <= R) {
            if (L & 1) res = max(res, tree[L++]);
            if (!(R & 1)) res = max(res, tree[R--]);
            L >>= 1;
            R >>= 1;
        }
        return res;
    }

    int firstAtLeast(int x, long long v, int node, int nl, int nr) {
        if (nr < x || tree[node] < v) return -1;
        if (nl == nr) return nl;
        int mid = (nl + nr) >> 1;
        int left = firstAtLeast(x, v, node << 1, nl, mid);
        if (left != -1) return left;
        return firstAtLeast(x, v, node << 1 | 1, mid + 1, nr);
    }

    int firstAtLeast(int x, long long v, int sz) {
        int ans = firstAtLeast(x, v, 1, 1, n);
        if (ans == -1 || ans > sz) return sz + 1;
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<long long> A(N + 1);
    for (int i = 1; i <= N; i++) cin >> A[i];

    SegTree st;
    st.build(A);

    while (Q--) {
        int type;
        cin >> type;
        if (type == 1) {
            int X;
            long long V;
            cin >> X >> V;
            st.update(X, V);
        } else if (type == 2) {
            int L, R;
            cin >> L >> R;
            cout << st.queryMax(L, R) << '\n';
        } else if (type == 3) {
            int X;
            long long V;
            cin >> X >> V;
            cout << st.firstAtLeast(X, V, N) << '\n';
        }
    }

    return 0;
}

