            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class SegmentTree {
        int n;
        int[] tree;

        SegmentTree(int[] arr) {
            n = arr.length - 1; // 1-indexed
            tree = new int[4 * n];
            build(1, 1, n, arr);
        }

        void build(int node, int l, int r, int[] arr) {
            if (l == r) {
                tree[node] = arr[l];
                return;
            }
            int mid = (l + r) >>> 1;
            build(node << 1, l, mid, arr);
            build(node << 1 | 1, mid + 1, r, arr);
            tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
        }

        void update(int idx, int val) {
            update(1, 1, n, idx, val);
        }

        void update(int node, int l, int r, int idx, int val) {
            if (l == r) {
                tree[node] = val;
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) update(node << 1, l, mid, idx, val);
            else update(node << 1 | 1, mid + 1, r, idx, val);
            tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
        }

        int queryMax(int ql, int qr) {
            return queryMax(1, 1, n, ql, qr);
        }

        int queryMax(int node, int l, int r, int ql, int qr) {
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            int res = Integer.MIN_VALUE;
            if (ql <= mid) res = Math.max(res, queryMax(node << 1, l, mid, ql, qr));
            if (qr > mid) res = Math.max(res, queryMax(node << 1 | 1, mid + 1, r, ql, qr));
            return res;
        }

        int firstAtLeast(int x, int v) {
            if (queryMax(x, n) < v) return n + 1;
            return firstAtLeast(1, 1, n, x, v);
        }

        int firstAtLeast(int node, int l, int r, int x, int v) {
            if (r < x || tree[node] < v) return n + 1;
            if (l == r) return l;
            int mid = (l + r) >>> 1;
            int left = firstAtLeast(node << 1, l, mid, x, v);
            if (left != n + 1) return left;
            return firstAtLeast(node << 1 | 1, mid + 1, r, x, v);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int n = fs.nextInt();
        int q = fs.nextInt();

        int[] a = new int[n + 1];
        for (int i = 1; i <= n; i++) a[i] = fs.nextInt();

        SegmentTree st = new SegmentTree(a);

        for (int i = 0; i < q; i++) {
            int type = fs.nextInt();
            if (type == 1) {
                int x = fs.nextInt();
                int v = fs.nextInt();
                st.update(x, v);
            } else if (type == 2) {
                int l = fs.nextInt();
                int r = fs.nextInt();
                out.append(st.queryMax(l, r)).append('\n');
            } else if (type == 3) {
                int x = fs.nextInt();
                int v = fs.nextInt();
                out.append(st.firstAtLeast(x, v)).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

import sys
input = sys.stdin.readline

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [0] * (2 * self.size)
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = max(self.tree[2*i], self.tree[2*i+1])

    def update(self, idx, value):
        pos = self.size + idx
        self.tree[pos] = value
        pos //= 2
        while pos:
            self.tree[pos] = max(self.tree[2*pos], self.tree[2*pos+1])
            pos //= 2

    def range_max(self, l, r):
        l += self.size
        r += self.size
        res = 0
        while l <= r:
            if l % 2 == 1:
                res = max(res, self.tree[l])
                l += 1
            if r % 2 == 0:
                res = max(res, self.tree[r])
                r -= 1
            l //= 2
            r //= 2
        return res

    def first_ge(self, x, v):
        # find first index >= x with value >= v
        if x >= self.n:
            return self.n + 1
        if self.range_max(x, self.n - 1) < v:
            return self.n + 1
        # binary search on segment tree
        l = x + self.size
        r = self.size + self.n - 1
        # go up to find covering segments
        while l <= r:
            if l % 2 == 1:
                if self.tree[l] >= v:
                    # descend at this node
                    pos = l
                    while pos < self.size:
                        if self.tree[2*pos] >= v:
                            pos = 2*pos
                        else:
                            pos = 2*pos + 1
                    return pos - self.size
                l += 1
            if r % 2 == 0:
                if self.tree[r] >= v:
                    pos = r
                    while pos < self.size:
                        if self.tree[2*pos] >= v:
                            pos = 2*pos
                        else:
                            pos = 2*pos + 1
                    return pos - self.size
                r -= 1
            l //= 2
            r //= 2
        return self.n + 1

