import sys

class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        size = 1
        while size < self.n:
            size <<= 1
        self.size = size
        self.seg = [-(10**18)] * (2 * size)
        for i in range(self.n):
            self.seg[size + i] = arr[i]
        for i in range(size - 1, 0, -1):
            self.seg[i] = max(self.seg[i << 1], self.seg[i << 1 | 1])

    def update(self, idx, val):
        p = self.size + idx
        self.seg[p] = val
        p >>= 1
        while p:
            self.seg[p] = max(self.seg[p << 1], self.seg[p << 1 | 1])
            p >>= 1

    def range_max(self, l, r):
        l += self.size
        r += self.size
        res = -(10**18)
        while l <= r:
            if l & 1:
                res = max(res, self.seg[l])
                l += 1
            if not (r & 1):
                res = max(res, self.seg[r])
                r -= 1
            l >>= 1
            r >>= 1
        return res

    def first_ge(self, x, v):
        if self.range_max(x, self.n - 1) < v:
            return self.n
        node = 1
        nl, nr = 0, self.size - 1
        while nl != nr:
            mid = (nl + nr) >> 1
            left = node << 1
            right = left | 1
            if x <= mid and self.seg[left] >= v:
                node = left
                nr = mid
            else:
                node = right
                nl = mid + 1
        return nl

def main():
    input = sys.stdin.readline
    N, Q = map(int, input().split())
    A = list(map(int, input().split()))
    st = SegmentTree(A)
    out = []

    for _ in range(Q):
        t, a, b = map(int, input().split())
        if t == 1:
            st.update(a - 1, b)
        elif t == 2:
            out.append(str(st.range_max(a - 1, b - 1)))
        else:
            ans = st.first_ge(a - 1, b) + 1
            out.append(str(ans))

    sys.stdout.write("\n".join(out))

